import { cn } from '@/lib/utils/cn';

interface Props {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  hint?: string;
  rows?: number;
}

export function TextAreaInput({ label, value, onChange, placeholder, hint, rows = 3 }: Props) {
  return (
    <div>
      <label className="mb-2 block text-sm font-bold text-text-primary">{label}</label>
      {hint && <p className="mb-2 text-xs text-text-muted">{hint}</p>}
      <textarea
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        rows={rows}
        className={cn(
          'w-full resize-none rounded-xl border border-border bg-surface p-3 text-sm',
          'text-text-primary placeholder:text-text-muted',
          'focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20',
        )}
      />
    </div>
  );
}