// ============================================================
// PromptBuilder — Full pipeline with Context + Strategy + Compatibility
// ============================================================

import type { TermMetadataFile, UseCaseId } from '@/types/knowledge.types';
import type { InteractionProtocolsFile, ProtocolId } from '@/types/protocol.types';
import type { ComposedPrompt, DnaSection } from '@/types/prompt.types';
import type { WizardAnswers } from '@/types/wizard.types';
import type { UserProfile } from '@/types/profile.types';
import { siteConfig } from '@/config/site.config';

import { selectTerms } from './TermSelector';
import { composeProtocol } from './ProtocolComposer';
import { renderTemplate } from './TemplateRenderer';
import { optimizeForModel } from './ModelOptimizer';
import { chainPrompt } from './ChainingComposer';
import { planStrategy, type StrategyFile } from './StrategyPlanner';
import { filterConflicts, type CompatibilityFile } from './CompatibilityChecker';
import { buildUserContext } from './ContextBuilder';


export interface BuildPromptInput {
  answers: WizardAnswers;
  termMetadata: TermMetadataFile;
  protocols: InteractionProtocolsFile;
  strategies: StrategyFile;
  compatibility: CompatibilityFile;
  profile?: UserProfile;
}

export function buildPrompt(input: BuildPromptInput): ComposedPrompt {
  const { answers, termMetadata, protocols, strategies, compatibility, profile } = input;

  // 1. Unified context
  const context = buildUserContext(answers, profile);

  // 2. Strategy
  const strategyDecision = planStrategy(strategies, answers);
  context.strategy = strategyDecision;

  // 3. Resolve protocol ID (coach override)
  const resolvedProtocolId: ProtocolId =
    answers.mode === 'learn-skill' && answers.learningStyle === 'coach'
      ? 'learn-skill-coach'
      : (answers.mode as ProtocolId);

  // 4. Select terms
  const selection = selectTerms(termMetadata, answers, compatibility, context.derived);

  // 5. Strategy boost + conflict filter
  const boosted = selection.selected.map((t) => {
    if (!strategyDecision.strategy.recommended_term_ids.includes(t.id)) return t;
    return {
      ...t,
      injection_weight: Object.fromEntries(
        Object.entries(t.injection_weight).map(([k, v]) => [k, v + 3]),
      ) as typeof t.injection_weight,
    };
  });
  const compatible = filterConflicts(compatibility, boosted);

  // 6. Protocol
  const composed = composeProtocol(protocols, resolvedProtocolId, {
    outputLanguage: answers.outputLanguage,
  });

  // 7. Render
  const rawPrompt = renderTemplate({
    answers,
    composed,
    terms: compatible,
    strategy: strategyDecision,
    derived: context.derived,
    usedProfile: context.usedProfile,
    profileName: profile?.name,
    protocolId: resolvedProtocolId,
  });

  // 8. Optimize for model
  const optimized = optimizeForModel(rawPrompt, answers.aiModel);

  // 9. Chain if requested (coach mode always single — interactive by design)
  const isChained =
    answers.promptFormat === 'chained' && answers.learningStyle !== 'coach';
  const prompts = isChained
    ? chainPrompt(optimized, answers.mode as UseCaseId)
    : [optimized];

  // 10. DNA sections
  const dnaSections = buildDnaSections(selection.categoryBreakdown);

  return {
    id: generateId(),
    prompts,
    meta: {
      mode: answers.mode as UseCaseId,
      protocolId: resolvedProtocolId,
      lengthMode: answers.lengthMode,
      selectedTermIds: compatible.map((t) => t.id),
      categoryBreakdown: selection.categoryBreakdown,
      language: answers.outputLanguage,
      isChained,
      totalChars: prompts.reduce((s, p) => s + p.length, 0),
      generatedAt: new Date().toISOString(),
      strategy: strategyDecision.strategy.id,
      strategyConfidence: strategyDecision.confidence,
      usedProfile: context.usedProfile,
      profileName: profile?.name,
    },
    dnaSections,
  };
}

function generateId(): string {
  return `p_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function buildDnaSections(breakdown: Record<string, number>): DnaSection[] {
  const total = Object.values(breakdown).reduce((s, n) => s + n, 0) || 1;
  const colors = siteConfig.theme.colors.categories as Record<string, string>;
  return Object.entries(breakdown).map(([category, count]) => ({
    name: humanizeCategory(category),
    category,
    weight: Math.round((count / total) * 100),
    color: colors[category] || siteConfig.theme.colors.primary,
    termIds: [],
  }));
}

function humanizeCategory(cat: string): string {
  const map: Record<string, string> = {
    'writing-hacks': 'Writing Hacks',
    storytelling: 'Storytelling',
    'camera-presence': 'Camera Presence',
    hooks: 'Hooks',
    cta: 'CTA',
    editing: 'Editing',
  };
  return map[cat] || cat;
}