// ============================================================
// ChainingComposer — splits a single prompt into 3 sequential prompts
// for workflows that benefit from staged execution
// ============================================================

import type { UseCaseId } from '@/types/knowledge.types';

interface ChainStage {
  title: string;
  objective: string;
  appendTask: string;
}

const CHAINS: Record<UseCaseId, ChainStage[]> = {
  'content-creation': [
    {
      title: 'Stage 1 — Discovery',
      objective: 'Ask the 5 discovery questions and wait for the user to answer. Do NOT write any content yet.',
      appendTask:
        '**END YOUR RESPONSE HERE.** Do not generate any script or post yet. Wait for the user to answer the 5 questions. Confirm each answer as you receive it.',
    },
    {
      title: 'Stage 2 — Generation',
      objective: 'Using the brief collected in Stage 1, generate the full script with 3 HOOK options, segmented CONTENT, and a matched CTA.',
      appendTask:
        'Assume the user has already answered the 5 discovery questions in the previous turn. Generate the full content now, following the CONTENT CREATION structure exactly. Include Visual & Editing notes after the script.',
    },
    {
      title: 'Stage 3 — Evaluation & Refinement',
      objective: 'Critique the generated content using the injected frameworks, score it out of 10, and propose 3 concrete improvements.',
      appendTask:
        'Now critique the content you just produced (or the version the user will paste). Score it out of 10 using the following criteria: Hook strength, Content clarity, CTA effectiveness, Pacing, and Editing potential. For each criterion, give 1 concrete improvement. End with one "if I could change ONE thing" recommendation.',
    },
  ],

  'learn-skill': [
    {
      title: 'Stage 1 — Deep Explanation',
      objective: 'Deliver the deep explanation with numbered rules, bilingual examples, and a summary table.',
      appendTask:
        'Deliver the full learn-skill explanation following the structure: one-line framing → numbered rules with bilingual examples → summary table → coach\'s tip. End there.',
    },
    {
      title: 'Stage 2 — Practice Exercises',
      objective: 'Provide 3 short practice exercises the user can do to apply the term immediately.',
      appendTask:
        'Now generate 3 practical exercises the user can complete within 10 minutes each, applying the term from Stage 1. For each: title + instructions + success criteria.',
    },
    {
      title: 'Stage 3 — Quiz & Grading',
      objective: 'Ask 5 quiz questions, wait for answers, then grade and explain.',
      appendTask:
        'Now write 5 quiz questions (mix of MCQ and short-answer) testing understanding of the term. Wait for the user to answer, then grade each answer and explain what they got right or wrong.',
    },
  ],

  'channel-strategy': [
    {
      title: 'Stage 1 — Diagnosis',
      objective: 'Ask the 5 diagnostic questions about the channel and analyze the answers.',
      appendTask:
        'Ask the 5 diagnostic questions (niche, platform, goal, status, presentation). Wait for answers. Then produce a one-page diagnosis: strengths, weaknesses, and 3 quick wins.',
    },
    {
      title: 'Stage 2 — 30-Day Plan',
      objective: 'Produce a detailed 30-day content plan (week by week).',
      appendTask:
        'Based on the diagnosis from Stage 1, produce a 30-day content plan divided into 4 weeks. For each week: theme + 3 content ideas + posting schedule + success metric.',
    },
    {
      title: 'Stage 3 — Performance System',
      objective: 'Build a tracking system the user can run weekly to measure progress.',
      appendTask:
        'Now build a weekly performance tracking system: metrics to measure (with target ranges), a 10-minute weekly review checklist, and a decision framework for "keep / adjust / kill" any content format.',
    },
  ],

  'idea-evaluation': [
    {
      title: 'Stage 1 — Score & Critique',
      objective: 'Score the idea out of 10 and list every flaw, each tied to a framework.',
      appendTask:
        'Deliver ONLY the score + direct critique (numbered flaws, each tied to a framework). Do NOT propose alternatives yet — end your response after the critique.',
    },
    {
      title: 'Stage 2 — 3 Alternative Angles',
      objective: 'Propose 3 alternative angles and 3 hooks for the strongest one.',
      appendTask:
        'Now propose 3 alternative angles (name + 2-line pitch + virality reason). Then pick the strongest angle and propose 3 hook options (comedic / curiosity / relatable).',
    },
    {
      title: 'Stage 3 — Refinement',
      objective: 'Deep-dive on the chosen angle with a full outline.',
      appendTask:
        'Assume the user picked one angle. Produce a full outline for it: hook (with 3 variants), 5-7 content beats, CTA, and a visual direction note. End with a go/no-go recommendation.',
    },
  ],

  custom: [
    {
      title: 'Stage 1 — Structure Proposal',
      objective: 'Confirm the selected terms and propose a structure.',
      appendTask:
        'Confirm the selected terms in one line, then propose a 2-3 pillar structure for applying them. Wait for user approval before proceeding.',
    },
    {
      title: 'Stage 2 — Term-by-Term Application',
      objective: 'Apply each term in balanced depth.',
      appendTask:
        'Apply each selected term with a real example and a practical tip. Divide your response space equally across all terms.',
    },
    {
      title: 'Stage 3 — Integration',
      objective: 'Show how the terms interconnect and produce one worked example.',
      appendTask:
        'Show how the applied terms interconnect, then produce one fully worked example that combines all of them.',
    },
  ],
};

export function chainPrompt(
  basePrompt: string,
  mode: UseCaseId,
): string[] {
  const stages = CHAINS[mode] || CHAINS['content-creation'];
  const prompts: string[] = [];

  for (const stage of stages) {
    prompts.push(
      `## ${stage.title}\n\n` +
        `> **Objective:** ${stage.objective}\n\n` +
        `${basePrompt}\n\n` +
        `---\n\n` +
        `## CHAIN INSTRUCTION\n\n` +
        `${stage.appendTask}\n`,
    );
  }
  return prompts;
}